+<script lang="ts">
+  import { FolderOpen, RotateCw } from '@lucide/svelte'
+
+  let {
+    filePath,
+    active,
+  }: {
+    filePath: string
+    active: boolean
+  } = $props()
+
+  let content: string | null = $state(null)
+  let binary = $state(false)
+  let truncated = $state(false)
+  let fileSize = $state(0)
+  let loading = $state(true)
+  let error: string | null = $state(null)
+
+  let fileName = $derived(filePath.split('/').pop() ?? filePath)
+  function shortenPath(p: string): string {
+    const parts = p.split('/')
+    if (parts.length <= 4) return p
+    return '.../' + parts.slice(-3).join('/')
+  }
+
+  let displayPath = $derived(shortenPath(filePath))
+
+  let lineNumbers = $derived(
+    content
+      ? content
+          .split('\n')
+          .map((_l, i) => i + 1)
+          .join('\n')
+      : '',
+  )
+
+  async function loadFile(): Promise<void> {
+    loading = true
+    error = null
+    content = null
+    binary = false
+    truncated = false
+    try {
+      const result = await window.api.readFile(filePath)
+      if (result.binary) {
+        binary = true
+        fileSize = result.size
+      } else {
+        content = result.content
+        truncated = result.truncated
+        fileSize = result.size
+      }
+    } catch (e) {
+      error = e instanceof Error ? e.message : 'Failed to read file'
+    } finally {
+      loading = false
+    }
+  }
+
+  function formatSize(bytes: number): string {
+    if (bytes < 1024) return `${bytes} B`
+    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
+    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
+  }
+
+  $effect(() => {
+    void filePath
+    loadFile()
+  })
+</script>
+
+<div class="editor-pane" class:active>
+  <div class="toolbar">
+    <div class="file-info">
+      <span class="file-name">{fileName}</span>
+      <span class="file-path">{displayPath}</span>
+      {#if fileSize > 0}
+        <span class="file-size">{formatSize(fileSize)}</span>
+      {/if}
+    </div>
+    <div class="toolbar-actions">
+      <button class="toolbar-btn" onclick={loadFile} title="Refresh" aria-label="Refresh file">
